package edu.alliance.medislot.model; public abstract class User { public enum Role{PATIENT,DOCTOR,ADMIN} private final long id;private final String name,email;private final Role role;protected User(long id,String name,String email,Role role){this.id=id;this.name=name;this.email=email;this.role=role;}public long getId(){return id;}public String getName(){return name;}public String getEmail(){return email;}public Role getRole(){return role;} }